import {
  dictionaryTableHas,
  loadDictionary,
  mergeDictionarySuggestions,
  restoreDictionaryFromSnapshot,
} from '../../editor/scripts/spellcheck-common.ts';
import { getKhmerSegmentationSegments } from './spellcheck-khmer-segmentation.ts';

const KHMER_BASE_LETTER_RE = /[\u1780-\u17B3]/u;
const KHMER_SEGMENTATION_SEPARATOR = '\u200B';

const workerRuntime = {
  checkCache: new Map(),
  dictionary: null,
  dictionaryConfig: null,
  loadPromise: null,
  segmentationCache: new Map(),
  suggestionDictionaries: [],
  suggestionDictionaryConfigs: [],
  suggestionCache: new Map(),
  suggestionLoadPromise: null,
};

function normalizeKhmerWord(word) {
  return String(word || '').replace(/^[\u200C\u200D]+|[\u200C\u200D]+$/gu, '');
}

function hasKhmerBaseLetter(word) {
  return KHMER_BASE_LETTER_RE.test(word);
}

function getDictionaryTable() {
  const dictionaryTable = workerRuntime.dictionary?.dictionaryTable;
  return dictionaryTable && typeof dictionaryTable === 'object'
    ? dictionaryTable
    : null;
}

function getSuggestionSourceDictionaries() {
  if (workerRuntime.suggestionDictionaries.length) {
    return workerRuntime.suggestionDictionaries.filter(
      (entry) => entry?.loaded,
    );
  }

  return workerRuntime.dictionary?.loaded ? [workerRuntime.dictionary] : [];
}

async function initializeKhmerSpellcheck(
  dictionaryConfig = null,
  dictionaryData = null,
) {
  if (dictionaryConfig && typeof dictionaryConfig === 'object') {
    workerRuntime.dictionaryConfig = dictionaryConfig;
  }

  if (workerRuntime.dictionary?.loaded) {
    return true;
  }

  if (!workerRuntime.loadPromise) {
    workerRuntime.loadPromise = Promise.resolve()
      .then(() => {
        if (dictionaryData && typeof dictionaryData === 'object') {
          workerRuntime.dictionary =
            restoreDictionaryFromSnapshot(dictionaryData);
          if (workerRuntime.dictionary?.loaded) {
            return true;
          }

          console.error(
            'Khmer spellcheck worker failed to restore serialized dictionary.',
          );
        }

        if (!workerRuntime.dictionaryConfig) {
          console.error(
            'Khmer spellcheck dictionary configuration is missing.',
          );
          return false;
        }

        return loadDictionary(workerRuntime.dictionaryConfig).then(
          (dictionary) => {
            workerRuntime.dictionary = dictionary?.loaded ? dictionary : null;
            if (!workerRuntime.dictionary) {
              console.error(
                'Khmer spellcheck dictionary did not finish loading.',
              );
              return false;
            }

            return true;
          },
        );
      })
      .catch((error) => {
        console.error('Failed to initialize Khmer spellcheck.', error);
        return false;
      })
      .then((ready) => {
        if (!ready) {
          workerRuntime.loadPromise = null;
        }

        return ready;
      });
  }

  return workerRuntime.loadPromise;
}

async function initializeKhmerSuggestionDictionaries(
  suggestDictionaryConfigs = null,
) {
  if (Array.isArray(suggestDictionaryConfigs)) {
    workerRuntime.suggestionDictionaryConfigs = suggestDictionaryConfigs.filter(
      (dictionaryConfig) =>
        dictionaryConfig && typeof dictionaryConfig === 'object',
    );
  } else if (
    suggestDictionaryConfigs &&
    typeof suggestDictionaryConfigs === 'object'
  ) {
    workerRuntime.suggestionDictionaryConfigs = [suggestDictionaryConfigs];
  }

  if (!workerRuntime.suggestionDictionaryConfigs.length) {
    return [];
  }

  if (
    workerRuntime.suggestionDictionaries.length ===
      workerRuntime.suggestionDictionaryConfigs.length &&
    workerRuntime.suggestionDictionaries.every((entry) => entry?.loaded)
  ) {
    return workerRuntime.suggestionDictionaries;
  }

  if (!workerRuntime.suggestionLoadPromise) {
    workerRuntime.suggestionLoadPromise = Promise.allSettled(
      workerRuntime.suggestionDictionaryConfigs.map((dictionaryConfig) =>
        loadDictionary(dictionaryConfig),
      ),
    ).then((results) => {
      const loadedSuggestionDictionaries = [];

      results.forEach((result, index) => {
        if (result.status === 'fulfilled' && result.value?.loaded) {
          loadedSuggestionDictionaries.push(result.value);
          return;
        }

        if (result.status === 'rejected') {
          console.error(
            `Failed to initialize Khmer spellcheck suggestion dictionary ${index + 1}.`,
            result.reason,
          );
          return;
        }

        console.error(
          `Khmer spellcheck suggestion dictionary ${index + 1} did not finish loading.`,
        );
      });

      workerRuntime.suggestionDictionaries = loadedSuggestionDictionaries;
      return workerRuntime.suggestionDictionaries;
    });
  }

  return workerRuntime.suggestionLoadPromise;
}

function isSpelledCorrectly(word) {
  const normalizedWord = normalizeKhmerWord(word);

  if (!workerRuntime.dictionary?.loaded || !normalizedWord) {
    return true;
  }

  if (!hasKhmerBaseLetter(normalizedWord)) {
    return true;
  }

  if (!workerRuntime.checkCache.has(normalizedWord)) {
    workerRuntime.checkCache.set(
      normalizedWord,
      workerRuntime.dictionary.check(normalizedWord),
    );
  }

  return workerRuntime.checkCache.get(normalizedWord) ?? true;
}

function hasExactDictionaryWord(word) {
  const normalizedWord = normalizeKhmerWord(word);

  if (!workerRuntime.dictionary?.loaded || !normalizedWord) {
    return false;
  }

  if (!hasKhmerBaseLetter(normalizedWord)) {
    return false;
  }

  const dictionaryTable = getDictionaryTable();
  if (!dictionaryTable) {
    return isSpelledCorrectly(normalizedWord);
  }

  // Map (typo-js 1.3.2) or plain object (older snapshots) — the helper
  // handles both shapes.
  return dictionaryTableHas(dictionaryTable, normalizedWord);
}

function getSegmentationSuggestion(word) {
  const normalizedWord = normalizeKhmerWord(word);

  if (
    !normalizedWord ||
    !workerRuntime.dictionary?.loaded ||
    !hasKhmerBaseLetter(normalizedWord) ||
    hasExactDictionaryWord(normalizedWord)
  ) {
    return '';
  }

  if (!workerRuntime.segmentationCache.has(normalizedWord)) {
    const segments = getKhmerSegmentationSegments(normalizedWord, (segment) =>
      hasExactDictionaryWord(segment),
    );

    workerRuntime.segmentationCache.set(
      normalizedWord,
      segments.length > 1 ? segments.join(KHMER_SEGMENTATION_SEPARATOR) : '',
    );
  }

  return workerRuntime.segmentationCache.get(normalizedWord) || '';
}

function shouldSkipSuggestionsForSegmentation(segmentationSuggestion) {
  if (typeof segmentationSuggestion !== 'string' || !segmentationSuggestion) {
    return false;
  }

  return segmentationSuggestion
    .split(KHMER_SEGMENTATION_SEPARATOR)
    .every((segment) => hasExactDictionaryWord(segment));
}

async function checkWords(words) {
  const ready = await initializeKhmerSpellcheck();
  const results = {};

  Array.from(new Set(words || [])).forEach((word) => {
    const normalizedWord = normalizeKhmerWord(word);

    if (!ready || !normalizedWord || !hasKhmerBaseLetter(normalizedWord)) {
      results[word] = true;
      return;
    }

    results[word] = isSpelledCorrectly(normalizedWord);
  });

  return results;
}

async function suggestWord(word, limit = 3) {
  const normalizedWord = normalizeKhmerWord(word);
  if (!normalizedWord || !hasKhmerBaseLetter(normalizedWord)) {
    return [];
  }

  const ready = await initializeKhmerSpellcheck();
  if (!ready || !workerRuntime.dictionary?.loaded) {
    return [];
  }

  if (workerRuntime.suggestionDictionaryConfigs.length) {
    await initializeKhmerSuggestionDictionaries();
  }

  const suggestionSourceDictionaries = getSuggestionSourceDictionaries();
  if (!suggestionSourceDictionaries.length) {
    return [];
  }

  if (!workerRuntime.suggestionCache.has(normalizedWord)) {
    const segmentationSuggestion = getSegmentationSuggestion(normalizedWord);

    workerRuntime.suggestionCache.set(
      normalizedWord,
      shouldSkipSuggestionsForSegmentation(segmentationSuggestion)
        ? []
        : mergeDictionarySuggestions(
            suggestionSourceDictionaries,
            normalizedWord,
            Math.max(1, limit || 3),
          ),
    );
  }

  return workerRuntime.suggestionCache.get(normalizedWord) || [];
}

async function segmentWord(word) {
  const normalizedWord = normalizeKhmerWord(word);
  if (!normalizedWord || !hasKhmerBaseLetter(normalizedWord)) {
    return '';
  }

  const ready = await initializeKhmerSpellcheck();
  if (!ready || !workerRuntime.dictionary?.loaded) {
    return '';
  }

  return getSegmentationSuggestion(normalizedWord);
}

globalThis.addEventListener('message', async (event) => {
  const { id, payload = {}, type } = event.data || {};

  try {
    let result = null;

    if (type === 'initialize') {
      if (Array.isArray(payload.suggestDictionaryConfigs)) {
        workerRuntime.suggestionDictionaryConfigs =
          payload.suggestDictionaryConfigs.filter(
            (dictionaryConfig) =>
              dictionaryConfig && typeof dictionaryConfig === 'object',
          );
      } else if (
        payload.suggestDictionaryConfig &&
        typeof payload.suggestDictionaryConfig === 'object'
      ) {
        workerRuntime.suggestionDictionaryConfigs = [
          payload.suggestDictionaryConfig,
        ];
      }

      result = {
        ready: await initializeKhmerSpellcheck(
          payload.dictionaryConfig,
          payload.dictionaryData,
        ),
      };
    } else if (type === 'checkWords') {
      result = await checkWords(payload.words);
    } else if (type === 'segment') {
      result = await segmentWord(payload.word);
    } else if (type === 'suggest') {
      result = await suggestWord(payload.word, payload.limit);
    } else {
      throw new Error(`Unsupported Khmer spellcheck worker message: ${type}`);
    }

    globalThis.postMessage({ id, result });
  } catch (error) {
    globalThis.postMessage({
      error: error instanceof Error ? error.message : String(error),
      id,
    });
  }
});
